25	/// Merge multiple ngram frequency files with given weights into a new one
26	struct Options {
27	    /// Directory name for resulting ngram frequency files
28	    out: String,
29	
30	    /// Pairs of weight and ngram frequency directory in the form path:weight
31	    components: Vec<WeightedComponent>,
32	}
