34	fn add<T: Clone + Eq + Hash>(weight: f64, res: &mut AHashMap<T, f64>, ngrams: &AHashMap<T, f64>) {
35	    ngrams.iter().fold(res, |acc, (c, w)| {
36	        let entry = acc.entry(c.clone()).or_default();
37	        *entry += weight * w;
38	
39	        acc
40	    });
41	}
