43	fn main() {
44	    dotenv::dotenv().ok();
45	    let options = Options::parse();
46	    env_logger::init();
47	
48	    let mut res_unigrams = AHashMap::default();
49	    let mut res_bigrams = AHashMap::default();
50	    let mut res_trigrams = AHashMap::default();
51	
52	    let mut target_unigrams_total: Option<f64> = None;
53	    let mut target_bigrams_total: Option<f64> = None;
54	    let mut target_trigrams_total: Option<f64> = None;
55	
56	    for component in options.components {
57	        log::info!("Processing {}...", component.1);
58	
59	        let p = Path::new(&component.1).join("1-grams.txt");
60	        let unigrams = Unigrams::from_file(p.to_str().unwrap())
61	            .unwrap_or_else(|_| panic!("Could not read 1-gramme file from '{:?}'.", &p));
62	
63	        let unigrams_total = unigrams.total_weight();
64	
65	        // first ngram file determines "absolute level"
66	        target_unigrams_total = target_unigrams_total.or(Some(unigrams_total));
67	        add(
68	            component.0 * target_unigrams_total.unwrap() / unigrams_total,
69	            &mut res_unigrams,
70	            &unigrams.grams,
71	        );
72	
73	        let p = Path::new(&component.1).join("2-grams.txt");
74	        let bigrams = Bigrams::from_file(p.to_str().unwrap())
