16	/// Configuration parameters for ngram processing
17	#[derive(Debug, Clone, Deserialize)]
18	pub struct NgramsConfig {
19	    /// Parameters for the increase in weight of common ngrams (with already high frequency).
20	    pub increase_common_ngrams: IncreaseCommonNgramsConfig,
21	}
