23	/// Configuration parameters for process of increasing the weight of common ngrams.
24	#[derive(Debug, Clone, Deserialize)]
25	pub struct IncreaseCommonNgramsConfig {
26	    /// Whether to increase the weight of common ngrams even further.
27	    pub enabled: bool,
28	    /// The critical fraction above which a ngram's weight will be increased.
29	    pub critical_fraction: f64,
30	    /// The slope with which the ngram's weight will be increased.
31	    /// The increment is performed linearly starting from the critical fraction,
32	    /// i.e. a ngram with weight equal the critical fraction is actually not affected.
33	    pub factor: f64,
34	    /// A minimum total weight (of all ngrams) that needs to be achieved. Otherwise no
35	    /// increment takes place.
36	    pub total_weight_threshold: f64,
37	}
38	
39	impl Default for IncreaseCommonNgramsConfig {
40	    fn default() -> Self {
41	        Self {
42	            enabled: true,
43	            critical_fraction: 0.001,
44	            factor: 2.0,
45	            total_weight_threshold: 20.0,
46	        }
47	    }
48	}
49	
50	pub fn increase_common_ngrams<T>(
51	    symbol_weights: &mut AHashMap<T, f64>,
52	    config: &IncreaseCommonNgramsConfig,
53	) {
54	    if !config.enabled {
55	        return;
56	    }
57	
58	    let total_weight: f64 = symbol_weights.values().sum();
59	    let critical_point = config.critical_fraction * total_weight;
60	
61	    symbol_weights.values_mut().for_each(|weight| {
62	        if *weight > critical_point && total_weight > config.total_weight_threshold {
63	            *weight += (*weight - critical_point) * (config.factor - 1.0);
64	        }
65	    });
66	}
