68	/// Holds a hashmap of unigrams (single chars) with corresponding frequency (here often called "weight").
69	#[derive(Clone, Debug)]
70	pub struct Unigrams {
71	    pub grams: AHashMap<char, f64>,
72	}
73	
74	fn process_special_characters(s: &str) -> String {
75	    s.replace("\\n", "\n").replace("\\\\", "\\")
76	}
77	
78	fn process_special_characters_inverse(s: &str) -> String {
79	    s.replace('\\', "\\\\").replace('\n', "\\n")
80	}
81	
82	impl Unigrams {
83	    /// Collect unigrams from given text.
84	    pub fn from_text(text: &str) -> Result<Self> {
85	        let mut grams = AHashMap::default();
86	        let chars = text.chars().filter(|c| *c != '\r');
87	        chars
88	            //.filter(|c| !c.is_whitespace())
89	            .for_each(|c| {
90	                grams.insert_or_add_weight(c, 1.0);
91	            });
92	
93	        Ok(Self { grams })
94	    }
95	
96	    /// Read unigrams and weights from a string containing lines with unigrams and their weights.
97	    pub fn from_frequencies_str(data: &str) -> Result<Self> {
98	        let mut grams = AHashMap::default();
99	        for line in data.lines() {
100	            let mut parts = line.trim_start().splitn(2, ' ');
101	            let weight: f64 = parts.next().unwrap().parse().unwrap();
102	            let unigram = parts.next().unwrap();
103	            let unigram = process_special_characters(unigram);
104	            let chars: Vec<char> = unigram.chars().collect();
105	            if chars.len() != 1 {
106	                log::error!("Len of unigram {} is unequad one: {:?}", unigram, chars);
107	            }
108	            let c = *chars.first().unwrap_or(&' ');
109	            grams.insert_or_add_weight(c, weight);
110	        }
111	
112	        Ok(Unigrams { grams })
113	    }
114	
115	    /// Read unigrams and weights from a file containing lines with unigrams and their weights.
116	    pub fn from_file(filename: &str) -> Result<Self> {
117	        let data = fs::read_to_string(filename)?;
118	        Unigrams::from_frequencies_str(&data)
119	    }
120	
121	    /// Total weight of all combined unigrams
122	    pub fn total_weight(&self) -> f64 {
123	        self.grams.values().sum()
124	    }
125	
126	    /// Return a reduced set of the unigrams containing only the most common unigrams up to a
127	    /// given combined fraction.
128	    pub fn tops(&self, fraction: f64) -> Self {
129	        let target_weight = fraction * self.total_weight();
130	        let mut total_weight = 0.0;
131	        let mut sorted_grams: Vec<(char, f64)> = self.grams.clone().into_iter().collect();
132	        sorted_grams.sort_by(|(_, w1), (_, w2)| w2.partial_cmp(w1).unwrap());
133	        let grams: AHashMap<char, f64> = sorted_grams
134	            .iter()
135	            .take_while(|(_c, w)| {
136	                let res = total_weight < target_weight;
137	                total_weight += *w;
138	
139	                res
140	            })
141	            .cloned()
142	            .collect();
143	
144	        log::info!(
145	            "Unigrams: Reducing from originally {} to the top {} ngrams.",
146	            self.grams.len(),
147	            grams.len()
148	        );
149	        Self { grams }
150	    }
151	
152	    // Return a reduced set of unigrams filtering out those containing a given character
153	    pub fn exclude_char(&self, exclude: &char) -> Self {
154	        let grams: AHashMap<char, f64> = self
155	            .grams
156	            .iter()
157	            .filter_map(|(c, w)| if *c == *exclude { None } else { Some((*c, *w)) })
158	            .collect();
159	        Self { grams }
160	    }
161	
162	    /// Save frequencies to file
163	    pub fn save_frequencies<T: AsRef<Path>>(&self, filename: T) -> Result<(), String> {
164	        let p = filename.as_ref();
165	        create_dir_all(p.parent().unwrap()).map_err(|e| {
166	            format!(
167	                "Unable to create directory '{}': {}",
168	                p.to_str().unwrap(),
169	                e
170	            )
171	        })?;
172	
173	        let mut grams: Vec<(char, f64)> = self.grams.iter().map(|(c, w)| (*c, *w)).collect();
174	        grams.sort_by(|(_, w1), (_, w2)| w2.partial_cmp(w1).unwrap());
175	
176	        let file = File::create(&filename)
177	            .map_err(|e| format!("Unable to create file '{}': {}", p.to_str().unwrap(), e))?;
178	        let mut buf_writer = BufWriter::new(file);
179	        grams.iter().for_each(|(c, w)| {
180	            let processed = process_special_characters_inverse(&c.to_string());
181	            writeln!(&mut buf_writer, "{} {}", w, processed).unwrap();
182	        });
183	
184	        Ok(())
185	    }
186	
187	    pub fn increase_common(&self, params: &IncreaseCommonNgramsConfig) -> Self {
188	        let mut grams = self.grams.clone();
189	        increase_common_ngrams(&mut grams, params);
190	        Self { grams }
191	    }
192	}
