#!/usr/bin/env python3
"""Tests for optimize.py -- the bridge from the freq.py corpus to the optimizer.

Run: python3 keyboards/svalboard/test_optimize.py

The thing worth pinning here is the layout string. It encodes the same class of
mistake `build.py`'s geometry guard exists to catch: get the cup order wrong and
you hand the optimizer a structurally perfect 40-character string describing a
keyboard nobody owns, and every number it reports back is confidently wrong.
"""

from __future__ import annotations

import unittest

import optimize


class LayoutStringTests(unittest.TestCase):
    def setUp(self):
        self.s = optimize.layout_string()

    def test_is_one_char_per_finger_switch(self):
        # 8 cups x 5 directions. Thumbs are absent on purpose: they are
        # fixed_keys in the optimizer's own config, which is what freezes them.
        self.assertEqual(len(self.s), 40)

    def test_cups_run_north_west_center_east_south(self):
        # config/keyboard/sval.yml orders each cup N, then low x, C, high x, S.
        # Left pinky: N=w, W=tab (no glyph -> free), C=r, E=-, S=x.
        self.assertEqual(self.s[0:5], "w□r-x")

    def test_right_hand_west_is_the_inward_lateral(self):
        # East is screen-right on BOTH hands, so on the right hand West is the
        # inward key. Right index: N=., W=,, C=a, E=:, S=u.
        self.assertEqual(self.s[20:25], ".,a:u")

    def test_right_ring_carries_the_ampersand_on_its_outer_lateral(self):
        # N=", W=;, C=i, E=&, S=y -- the README's "rarest thing on this layer
        # bar @, on one of the worst keys here, which is the point".
        self.assertEqual(self.s[30:35], '";i&y')

    def test_every_letter_appears_exactly_once(self):
        for c in "REDACTED":
            self.assertEqual(self.s.count(c), 1, f"{c!r} appears {self.s.count(c)}x")

    def test_the_seven_promoted_symbols_each_appear_once(self):
        for c in "-:()&@~":
            self.assertEqual(self.s.count(c), 1, f"{c!r} appears {self.s.count(c)}x")

    def test_non_glyph_keys_become_free_positions(self):
        # tab is the only layer-0 finger key with no single-character glyph.
        self.assertEqual(self.s.count("□"), 1)


class FixedSetTests(unittest.TestCase):
    def test_fixed_chars_are_the_punctuation_outside_the_scope(self):
        # Scope is alphas + the 7 promoted symbols. Everything else printable on
        # layer 0 is pinned via --fix, because sval.yml marks all 40 finger keys
        # permutable and there is no per-key freeze short of editing it.
        self.assertEqual(set(optimize.FIXED), set(",./;'\""))

    def test_fixed_and_floating_together_cover_the_layout(self):
        s = optimize.layout_string()
        floating = set(s) - set(optimize.FIXED) - {"□"}
        self.assertEqual(floating, set("REDACTED:()&@~"))


class WeightTests(unittest.TestCase):
    def test_every_freq_source_is_weighted(self):
        # Adding a corpus to freq.py without deciding what it is worth would
        # otherwise silently drop it from the blend.
        import freq

        self.assertEqual(set(optimize.WEIGHTS), set(freq.SOURCES))

    def test_weights_sum_to_one(self):
        self.assertAlmostEqual(sum(optimize.WEIGHTS.values()), 1.0, places=6)


class CorpusCleaningTests(unittest.TestCase):
    def test_path_markers_are_stripped_from_the_code_corpus(self):
        # iter_code_text prefixes every file with "\x00PATH:<rel>\n" so that
        # code_split() can bucket by extension. Feeding those to the ngram
        # generator would count "PATH:" and the repo's own directory names as
        # things a person typed.
        text = "\x00PATH:a.py\nbody a\n\x00PATH:b/c.nix\nbody b"

        self.assertEqual(optimize.strip_path_markers(text), "body a\nbody b")

    def test_text_without_markers_is_unchanged(self):
        self.assertEqual(optimize.strip_path_markers("plain\ntext"), "plain\ntext")


